package com.smartbank.service;
import com.smartbank.entity.PasswordResetToken; import com.smartbank.repository.*; import jakarta.mail.internet.MimeMessage; import org.springframework.beans.factory.ObjectProvider; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.mail.javamail.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.Instant; import java.util.*;
@Service public class AccountSecurityService {
 private final UserRepository users; private final PasswordResetRepository resets; private final PasswordEncoder passwords; private final JavaMailSender mail; private final String mailHost,frontendUrl,mailFrom;
 public AccountSecurityService(UserRepository users,PasswordResetRepository resets,PasswordEncoder passwords,ObjectProvider<JavaMailSender> mail,@Value("${MAIL_HOST:}") String mailHost,@Value("${app.frontend-url}") String frontendUrl,@Value("${MAIL_FROM:no-reply@smartbank.local}") String mailFrom){this.users=users;this.resets=resets;this.passwords=passwords;this.mail=mail.getIfAvailable();this.mailHost=mailHost;this.frontendUrl=frontendUrl;this.mailFrom=mailFrom;}
 @Transactional public void requestReset(String email){var user=users.findByEmailIgnoreCase(email.trim()).filter(u->u.active).orElse(null);if(user==null||mail==null||mailHost.isBlank())return;resets.deleteByExpiresAtBefore(Instant.now());resets.deleteByUserId(user.id);byte[] random=new byte[32];new SecureRandom().nextBytes(random);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(random);PasswordResetToken token=new PasswordResetToken();token.user=user;token.tokenHash=hash(raw);token.expiresAt=Instant.now().plusSeconds(900);resets.save(token);try{MimeMessage message=mail.createMimeMessage();MimeMessageHelper helper=new MimeMessageHelper(message,false,StandardCharsets.UTF_8.name());helper.setFrom(mailFrom);helper.setTo(user.email);helper.setSubject("Reset your SmartBank password");helper.setText("A password reset was requested for your SmartBank account. Open this link within 15 minutes:\n\n"+frontendUrl+"/reset-password?token="+raw+"\n\nIf you did not request this, you can ignore this email.");mail.send(message);}catch(Exception e){resets.delete(token);}}
 @Transactional public void reset(String raw,String newPassword){if(raw==null||raw.length()<32)throw invalid();var token=resets.findByTokenHashAndUsedAtIsNull(hash(raw)).filter(t->t.expiresAt.isAfter(Instant.now())&&t.user.active).orElseThrow(AccountSecurityService::invalid);token.user.passwordHash=passwords.encode(newPassword);token.usedAt=Instant.now();}
 @Transactional public void changePassword(String email,String current,String next){var user=users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));if(!passwords.matches(current,user.passwordHash))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Current password is incorrect.");user.passwordHash=passwords.encode(next);resets.deleteByUserId(user.id);}
 private String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private static ResponseStatusException invalid(){return new ResponseStatusException(HttpStatus.BAD_REQUEST,"This password reset link is invalid or expired. Request a new one.");}
}
